import type { Metadata } from "next";

// Share images are 1200x630, generated by scripts/make-share-images.mjs.
export function pageMetadata(title: string, description: string, path: string, image: string, imageAlt: string): Metadata {
  const images = [{ url: image, width: 1200, height: 630, alt: imageAlt }];
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, type: "website", siteName: "RK Group of Industries", locale: "en_PK", images },
    twitter: { card: "summary_large_image", title, description, images },
  };
}
